// nfkdSweepCase is a `[code_point, slug("a"+chr(cp)+"b")]` pair.
type nfkdSweepCase struct {
	CodePoint rune
	Slug      string
}

func (c *nfkdSweepCase) UnmarshalJSON(data []byte) error {
	var raw [2]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return err
	}
	if err := json.Unmarshal(raw[0], &c.CodePoint); err != nil {
		return err
	}
	return json.Unmarshal(raw[1], &c.Slug)
}

