var (
	fixtureOnce sync.Once
	fixtureData utilsFixture
	fixtureErr  error
)

func loadFixture(t *testing.T) *utilsFixture {
	t.Helper()

	fixtureOnce.Do(func() {
		raw, err := os.ReadFile(filepath.Join("testdata", "utils", "expected.json"))
		if err != nil {
			fixtureErr = err
			return
		}
		fixtureErr = json.Unmarshal(raw, &fixtureData)
	})
	if fixtureErr != nil {
		t.Fatalf("loading testdata/utils/expected.json: %v", fixtureErr)
	}

	return &fixtureData
}

// pythonError strips the `TypeName: ` prefix the probe records so the message
// can be compared against a Go error's text.
func pythonError(recorded string) string {
	_, message, found := strings.Cut(recorded, ": ")
	if !found {
		return ""
	}
	return message
}

// ---------------------------------------------------------------------------
// generate_urlsafe_hash / slug / get_current_user_name
// ---------------------------------------------------------------------------

func TestGenerateURLSafeHash(t *testing.T) {
	for _, tc := range loadFixture(t).URLSafeHash {
		t.Run(tc.Hex, func(t *testing.T) {
			if got := GenerateURLSafeHash(tc.Input); got != tc.Output {
				t.Errorf("GenerateURLSafeHash(%q) = %q, oracle says %q", tc.Input, got, tc.Output)
			}
		})
	}
}

// TestGenerateURLSafeHashStripsHighBytes pins the two properties the table can
// only sample: a non-ASCII run contributes nothing, so any two strings that
// differ only outside ASCII collide, and the C0 controls are inside the kept
// range rather than stripped with them.
func TestGenerateURLSafeHashStripsHighBytes(t *testing.T) {
	if GenerateURLSafeHash("日本語") != GenerateURLSafeHash("") {
		t.Error("a wholly non-ASCII string must hash as the empty string")
	}
	if GenerateURLSafeHash("a日本語b") != GenerateURLSafeHash("ab") {
		t.Error("a non-ASCII run must be deleted, not replaced")
	}
	if GenerateURLSafeHash("\x00\x01\x7f") == GenerateURLSafeHash("") {
		t.Error("ASCII controls are inside [\\x00-\\x7F] and must survive")
	}
}

// TestGenerateURLSafeHashAlphabet pins the shape callers depend on: the result
// is alphanumeric, so it is safe in a container name, a network name and a
// Kubernetes namespace, and it is never the fixed 22 characters of a base64
// digest because '-' and '_' are deleted rather than substituted.
func TestGenerateURLSafeHashAlphabet(t *testing.T) {
	alphanumeric := regexp.MustCompile(`^[A-Za-z0-9]*$`)

	sawShort := false
	for _, tc := range loadFixture(t).URLSafeHash {
		if !alphanumeric.MatchString(tc.Output) {
			t.Errorf("hash of %q is %q, which is not alphanumeric", tc.Input, tc.Output)
		}
		if len(tc.Output) > 22 {
			t.Errorf("hash of %q is %d characters, more than the 22 of a trimmed digest", tc.Input, len(tc.Output))
		}
		if len(tc.Output) < 22 {
			sawShort = true
		}
	}
	if !sawShort {
		t.Error("no vector exercised the shortening effect of deleting '-' and '_'")
	}
}

func TestSlug(t *testing.T) {
	for _, tc := range loadFixture(t).Slug {
		t.Run(tc.Hex, func(t *testing.T) {
			if got := Slug(tc.Input); got != tc.Output {
				t.Errorf("Slug(%q) = %q, oracle says %q", tc.Input, got, tc.Output)
			}
		})
	}
}

// TestSlugNFKDSweep is the parity check between Go's x/text NFKD and CPython's
// unicodedata: every code point above ASCII whose NFKD normalisation yields
// anything ASCII, which is the complete set on which Slug can behave
// differently from a plain "delete non-ASCII".
func TestSlugNFKDSweep(t *testing.T) {
	sweep := loadFixture(t).SlugNFKDSweep
	if len(sweep) < 2000 {
		t.Fatalf("sweep has only %d code points; the fixture looks truncated", len(sweep))
	}

	for _, tc := range sweep {
		input := "a" + string(tc.CodePoint) + "b"
		if got := Slug(input); got != tc.Slug {
			t.Errorf("Slug(%q) with U+%04X = %q, oracle says %q", input, tc.CodePoint, got, tc.Slug)
		}
	}
}

func TestUserNameChain(t *testing.T) {
	for _, tc := range loadFixture(t).UserNameChain {
		t.Run(tc.Username+"@"+tc.Hostname, func(t *testing.T) {
			hash := GenerateURLSafeHash(tc.Hostname)
			if hash != tc.HostnameHash {
				t.Fatalf("hostname hash of %q = %q, oracle says %q", tc.Hostname, hash, tc.HostnameHash)
			}
			if got := Slug(tc.Username + "-" + hash); got != tc.Output {
				t.Errorf("user name for %q@%q = %q, oracle says %q", tc.Username, tc.Hostname, got, tc.Output)
			}
		})
	}
}

// TestUserNameChainIsHostSensitive pins the property the naming scheme exists
// for: the same login on two hosts must not produce the same identity, and a
// hostname that differs only in case must not fold together (the hostname is
// hashed before it is slugged, so the case survives into the digest).
func TestUserNameChainIsHostSensitive(t *testing.T) {
	a := Slug("root" + "-" + GenerateURLSafeHash("kathara-host"))
	b := Slug("root" + "-" + GenerateURLSafeHash("other-host"))
	c := Slug("root" + "-" + GenerateURLSafeHash("KATHARA-HOST"))

	if a == b {
		t.Error("two hosts produced the same user name")
	}
	if a == c {
		t.Error("hostname case must reach the digest, so it must change the user name")
	}
}

