func TestHumanReadableBytes(t *testing.T) {
	for _, tc := range loadFixture(t).HumanReadableBytes {
		t.Run(tc.Size, func(t *testing.T) {
			size, err := strconv.ParseInt(tc.Size, 10, 64)
			if err != nil {
				t.Fatalf("fixture size %q: %v", tc.Size, err)
			}

			got, err := HumanReadableBytes(size)
			if tc.Error != "" {
				if err == nil {
					t.Fatalf("HumanReadableBytes(%d) = %q, oracle raised %s", size, got, tc.Error)
				}
				if err.Error() != pythonError(tc.Error) {
					t.Errorf("HumanReadableBytes(%d) error = %q, oracle says %q", size, err, pythonError(tc.Error))
				}
				if !errors.Is(err, kerrors.ErrValue) {
					t.Errorf("HumanReadableBytes(%d) error is not classified Value", size)
				}
				return
			}
			if err != nil {
				t.Fatalf("HumanReadableBytes(%d): %v", size, err)
			}
			if got != tc.Output {
				t.Errorf("HumanReadableBytes(%d) = %q, oracle says %q", size, got, tc.Output)
			}
		})
	}
}

// TestHumanReadableBytesBulk is the 2,900-value sweep: every 2**k
// neighbourhood plus a seeded random sample. It is what catches a rounding
// mode or a float-repr difference that the hand-picked table would miss.
func TestHumanReadableBytesBulk(t *testing.T) {
	bulk := loadFixture(t).HumanReadableBytesBulk
	if len(bulk) < 2000 {
		t.Fatalf("bulk sweep has only %d values; the fixture looks truncated", len(bulk))
	}

	for _, tc := range bulk {
		size, err := strconv.ParseInt(tc[0], 10, 64)
		if err != nil {
			t.Fatalf("fixture size %q: %v", tc[0], err)
		}
		got, err := HumanReadableBytes(size)
		if err != nil {
			t.Fatalf("HumanReadableBytes(%d): %v", size, err)
		}
		if got != tc[1] {
			t.Errorf("HumanReadableBytes(%d) = %q, oracle says %q", size, got, tc[1])
		}
	}
}

// TestHumanReadableBytesFloatRepr pins the two shapes the format has to keep:
// an integral value prints with a ".0" that Go's %v would drop, and the
// exponent is picked before the rounding so a value just under a power comes
// out as "1024.0 KB" and never as "1.0 MB".
func TestHumanReadableBytesFloatRepr(t *testing.T) {
	for _, tc := range []struct {
		size int64
		want string
	}{
		{0, "0 B"},
		{1, "1.0 B"},
		{1024, "1.0 KB"},
		{1048575, "1024.0 KB"},
		{1048576, "1.0 MB"},
		{10000, "9.77 KB"},
		// float(2**50-1)/float(2**50) rounds to exactly 1.0, selecting the next
		// unit in Python.
		{1125899906842623, "1.0 PB"},
	} {
		got, err := HumanReadableBytes(tc.size)
		if err != nil {
			t.Fatalf("HumanReadableBytes(%d): %v", tc.size, err)
		}
		if got != tc.want {
			t.Errorf("HumanReadableBytes(%d) = %q, want %q", tc.size, got, tc.want)
		}
	}
}

