func TestCurrentVersion(t *testing.T) {
	fixture := loadFixture(t)
	if CurrentVersion != fixture.Version.CurrentVersion {
		t.Errorf("CurrentVersion = %q, oracle says %q", CurrentVersion, fixture.Version.CurrentVersion)
	}
	if CurrentVersion != fixture.KatharaVersion {
		t.Errorf("CurrentVersion = %q, fixture was generated against %q", CurrentVersion, fixture.KatharaVersion)
	}
}

func TestParseDockerEngineVersion(t *testing.T) {
	for _, tc := range loadFixture(t).Version.DockerEngine {
		t.Run(tc.Input, func(t *testing.T) {
			if tc.Error != "" {
				t.Fatalf("fixture records an error for %q, which the char loop cannot raise: %s", tc.Input, tc.Error)
			}
			if got := ParseDockerEngineVersion(tc.Input); got != tc.Output {
				t.Errorf("ParseDockerEngineVersion(%q) = %q, oracle says %q", tc.Input, got, tc.Output)
			}
		})
	}
}

// TestParseDockerEngineVersionQuirks names the two behaviours that make the
// character loop worth copying instead of replacing with a regexp, both
// sampled by the table above.
func TestParseDockerEngineVersionQuirks(t *testing.T) {
	// A part keeps its leading digit run and the loop continues, so a
	// pre-release suffix is not truncated at — it is deleted from the middle,
	// and the parts behind it move up.
	if got := ParseDockerEngineVersion("20.10-beta.3"); got != "20.10.3" {
		t.Errorf("ParseDockerEngineVersion(\"20.10-beta.3\") = %q, want \"20.10.3\"", got)
	}
	// A part with no leading digit stops the loop outright, so a leading "v"
	// or a leading space empties the whole version.
	for _, input := range []string{"v20.10.14", " 1.2", "abc"} {
		if got := ParseDockerEngineVersion(input); got != "" {
			t.Errorf("ParseDockerEngineVersion(%q) = %q, want \"\"", input, got)
		}
	}
	// str.isdigit() is wider than int() accepts, which is observable exactly
	// here: the superscript survives the sanitiser and then fails the parse.
	if got := ParseDockerEngineVersion("1².2"); got != "1².2" {
		t.Errorf("ParseDockerEngineVersion(\"1².2\") = %q, want \"1².2\"", got)
	}
	if _, err := ParseVersion("1².2"); err == nil {
		t.Error("ParseVersion must reject the superscript ParseDockerEngineVersion keeps")
	}
}

func TestParseVersion(t *testing.T) {
	for _, tc := range loadFixture(t).Version.Parse {
		t.Run(tc.Input, func(t *testing.T) {
			got, err := ParseVersion(tc.Input)

			if tc.Error != "" {
				if err == nil {
					t.Fatalf("ParseVersion(%q) = %v, oracle raised %s", tc.Input, got, tc.Error)
				}
				if err.Error() != pythonError(tc.Error) {
					t.Errorf("ParseVersion(%q) error = %q, oracle says %q", tc.Input, err, pythonError(tc.Error))
				}
				if !errors.Is(err, kerrors.ErrValue) {
					t.Errorf("ParseVersion(%q) error is not classified Value", tc.Input)
				}
				return
			}
			if err != nil {
				t.Fatalf("ParseVersion(%q): %v", tc.Input, err)
			}
			if len(got) != len(tc.Parts) {
				t.Fatalf("ParseVersion(%q) = %v, oracle says %v", tc.Input, got, tc.Parts)
			}
			for i := range got {
				if got[i] != tc.Parts[i] {
					t.Fatalf("ParseVersion(%q) = %v, oracle says %v", tc.Input, got, tc.Parts)
				}
			}
		})
	}
}

func TestLessThan(t *testing.T) {
	for _, tc := range loadFixture(t).Version.LessThan {
		t.Run(tc.A+"<"+tc.B, func(t *testing.T) {
			got, err := LessThan(tc.A, tc.B)

			if tc.Error != "" {
				if err == nil {
					t.Fatalf("LessThan(%q, %q) = %v, oracle raised %s", tc.A, tc.B, got, tc.Error)
				}
				if err.Error() != pythonError(tc.Error) {
					t.Errorf("LessThan(%q, %q) error = %q, oracle says %q", tc.A, tc.B, err, pythonError(tc.Error))
				}
				return
			}
			if err != nil {
				t.Fatalf("LessThan(%q, %q): %v", tc.A, tc.B, err)
			}
			if got != tc.LessThan {
				t.Errorf("LessThan(%q, %q) = %v, oracle says %v", tc.A, tc.B, got, tc.LessThan)
			}
		})
	}
}

// TestLessThanIsTupleComparison pins the rule that makes this not a semver
// compare: a prefix is smaller than what extends it, so 3.8 < 3.8.1 and
// 0 < 0.0, and a component is compared numerically so 3.9 < 3.10.
func TestLessThanIsTupleComparison(t *testing.T) {
	for _, tc := range []struct {
		a, b string
		want bool
	}{
		{"3.8", "3.8.1", true},
		{"3.8.1", "3.8", false},
		{"0", "0.0", true},
		{"0.0", "0", false},
		{"3.9", "3.10", true},
		{"3.10", "3.9", false},
		{"007.008", "7.8", false},
		{"7.8", "007.008", false},
	} {
		got, err := LessThan(tc.a, tc.b)
		if err != nil {
			t.Fatalf("LessThan(%q, %q): %v", tc.a, tc.b, err)
		}
		if got != tc.want {
			t.Errorf("LessThan(%q, %q) = %v, want %v", tc.a, tc.b, got, tc.want)
		}
	}
}

