func TestArchitectureOf(t *testing.T) {
	for _, tc := range loadFixture(t).Architecture.Cases {
		t.Run(tc.Machine, func(t *testing.T) {
			got, err := architectureOf(tc.Machine)

			if tc.Error != "" {
				if err == nil {
					t.Fatalf("architectureOf(%q) = %q, oracle raised %s", tc.Machine, got, tc.Error)
				}
				if err.Error() != pythonError(tc.Error) {
					t.Errorf("architectureOf(%q) error = %q, oracle says %q", tc.Machine, err, pythonError(tc.Error))
				}
				var hostErr *kerrors.HostArchError
				if !errors.As(err, &hostErr) {
					t.Fatalf("architectureOf(%q) error is not a HostArchError", tc.Machine)
				}
				if hostErr.Arch != strings.ToLower(tc.Machine) {
					t.Errorf("HostArchError.Arch = %q, want the lower-cased %q", hostErr.Arch, tc.Machine)
				}
				return
			}
			if err != nil {
				t.Fatalf("architectureOf(%q): %v", tc.Machine, err)
			}
			if got != tc.Output {
				t.Errorf("architectureOf(%q) = %q, oracle says %q", tc.Machine, got, tc.Output)
			}
		})
	}
}

// TestGetArchitectureReadsTheKernel pins that the value comes from uname and
// not from this binary: it must agree with what the oracle read from the same
// host, which a GOARCH-derived answer would only do by coincidence.
func TestGetArchitectureReadsTheKernel(t *testing.T) {
	fixture := loadFixture(t)

	machine := machineName()
	if machine != fixture.Architecture.HostMachine {
		t.Skipf("fixture recorded machine %q, this host reports %q",
			fixture.Architecture.HostMachine, machine)
	}

	got, err := GetArchitecture()
	if err != nil {
		t.Fatalf("GetArchitecture: %v", err)
	}
	if got != fixture.Live.Architecture {
		t.Errorf("GetArchitecture() = %q, oracle says %q", got, fixture.Live.Architecture)
	}
}

