func TestParseCDMACAddress(t *testing.T) {
	for _, tc := range loadFixture(t).CDMac {
		t.Run(tc.Input, func(t *testing.T) {
			cd, mac, err := ParseCDMACAddress(tc.Input)

			if tc.Error != "" {
				if err == nil {
					t.Fatalf("ParseCDMACAddress(%q) = (%q, %q), oracle raised %s", tc.Input, cd, mac, tc.Error)
				}
				if err.Error() != pythonError(tc.Error) {
					t.Errorf("ParseCDMACAddress(%q) error = %q, oracle says %q", tc.Input, err, pythonError(tc.Error))
				}
				if !errors.Is(err, kerrors.ErrSyntax) {
					t.Errorf("ParseCDMACAddress(%q) error is not classified Syntax", tc.Input)
				}
				return
			}
			if err != nil {
				t.Fatalf("ParseCDMACAddress(%q): %v", tc.Input, err)
			}
			if cd != tc.CD {
				t.Errorf("ParseCDMACAddress(%q) cd = %q, oracle says %q", tc.Input, cd, tc.CD)
			}

			// Python's None becomes the empty string; the other branch can
			// never produce an empty MAC, so the two are not confusable.
			wantMac := ""
			if tc.Mac != nil {
				wantMac = *tc.Mac
			}
			if mac != wantMac {
				t.Errorf("ParseCDMACAddress(%q) mac = %q, oracle says %q", tc.Input, mac, wantMac)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// check_single_not_none_var / check_required_single_not_none_var
// ---------------------------------------------------------------------------

func TestCheckNotNoneVars(t *testing.T) {
	for _, tc := range loadFixture(t).CheckVars {
		name := strings.Join(tc.Names, ",")
		if tc.Required {
			name = "required/" + name
		}

		t.Run(name, func(t *testing.T) {
			params := make([]Param, 0, len(tc.Names))
			for i, paramName := range tc.Names {
				params = append(params, Param{Name: paramName, Present: tc.Present[i]})
			}

			var err error
			if tc.Required {
				err = CheckRequiredSingleNotNoneVar(params...)
			} else {
				err = CheckSingleNotNoneVar(params...)
			}

			if tc.Error == "" {
				if err != nil {
					t.Fatalf("unexpected error: %v", err)
				}
				return
			}
			if err == nil {
				t.Fatalf("no error, oracle says %q", tc.Error)
			}
			if err.Error() != tc.Error {
				t.Errorf("error = %q, oracle says %q", err, tc.Error)
			}
			if !errors.Is(err, kerrors.ErrInvocation) {
				t.Error("error is not classified Invocation")
			}
		})
	}
}

func TestCheckNotNoneVarsKeepsCallOrder(t *testing.T) {
	params := []Param{
		{Name: "lab_hash", Present: true},
		{Name: "lab_name", Present: true},
		{Name: "lab", Present: false},
	}

	err := CheckSingleNotNoneVar(params...)
	if err == nil {
		t.Fatal("two supplied parameters must be an error")
	}
	if err.Error() != "You must specify only a parameter among lab_hash, lab_name, lab" {
		t.Errorf("error = %q", err)
	}

	reversed := []Param{params[2], params[1], params[0]}
	err = CheckSingleNotNoneVar(reversed...)
	if err == nil {
		t.Fatal("two supplied parameters must be an error")
	}
	if err.Error() != "You must specify only a parameter among lab, lab_name, lab_hash" {
		t.Errorf("reordered call site must reorder the message, got %q", err)
	}
}

// ---------------------------------------------------------------------------
// re_search_fail
// ---------------------------------------------------------------------------

// goRegexpFor translates the one pattern re_search_fail is called with
// (Setting.py:216,221) into RE2. Python's `$` also matches immediately before
// a trailing newline; Go's does not without `(?m)`, which would also change
// `^`, so the newline is spelled out instead.
func goRegexpFor(pythonPattern string) string {
	return strings.TrimSuffix(pythonPattern, "$") + `\n?$`
}

func TestReSearchFail(t *testing.T) {
	for _, tc := range loadFixture(t).ReSearchFail {
		t.Run(tc.Expr+"/"+strconv.Quote(tc.Line), func(t *testing.T) {
			expression := regexp.MustCompile(goRegexpFor(tc.Expr))

			matches, err := ReSearchFail(expression, tc.Line)

			if tc.Error != "" {
				if err == nil {
					t.Fatalf("ReSearchFail(%q) = %v, oracle raised %s", tc.Line, matches, tc.Error)
				}
				if !errors.Is(err, ErrNoMatch) {
					t.Errorf("error is %v, want ErrNoMatch", err)
				}
				return
			}
			if err != nil {
				t.Fatalf("ReSearchFail(%q): %v", tc.Line, err)
			}
			if len(matches) == 0 {
				t.Fatal("a successful search must return at least group 0")
			}
			// The translated pattern absorbs the trailing newline that
			// Python's `$` merely allows, so group 0 can be one byte longer.
			if strings.TrimSuffix(matches[0], "\n") != tc.Match {
				t.Errorf("group 0 = %q, oracle says %q", matches[0], tc.Match)
			}
		})
	}
}

// TestReSearchFailNeedsTheNewlineSpelledOut is the reason goRegexpFor exists:
// the untranslated pattern disagrees with Python on exactly one of the
// fixture's lines, and silently — it rejects a settings value Python accepts.
func TestReSearchFailNeedsTheNewlineSpelledOut(t *testing.T) {
	literal := regexp.MustCompile(`^[a-z]+_?[a-z_]+$`)

	if _, err := ReSearchFail(literal, "kathara\n"); !errors.Is(err, ErrNoMatch) {
		t.Fatal("RE2's `$` is end-of-text; the literal pattern must reject a trailing newline")
	}

	translated := regexp.MustCompile(goRegexpFor(`^[a-z]+_?[a-z_]+$`))
	if _, err := ReSearchFail(translated, "kathara\n"); err != nil {
		t.Fatalf("the translated pattern must accept it, as Python does: %v", err)
	}
	if _, err := ReSearchFail(translated, "kathara\nnope"); !errors.Is(err, ErrNoMatch) {
		t.Fatal("the newline must only be allowed at the very end")
	}
}

// ---------------------------------------------------------------------------
// Module constants and the live identity
// ---------------------------------------------------------------------------

func TestModuleConstants(t *testing.T) {
	fixture := loadFixture(t)

	if got := ReservedMachineNames(); !equalStrings(got, fixture.Live.ReservedMachineNames) {
		t.Errorf("ReservedMachineNames() = %v, oracle says %v", got, fixture.Live.ReservedMachineNames)
	}
	if got := ExcludedFiles(); !equalStrings(got, fixture.Live.ExcludedFiles) {
		t.Errorf("ExcludedFiles() = %v, oracle says %v", got, fixture.Live.ExcludedFiles)
	}

	for _, name := range fixture.Live.ReservedMachineNames {
		if !IsReservedMachineName(name) {
			t.Errorf("IsReservedMachineName(%q) = false", name)
		}
		if IsReservedMachineName(strings.ToUpper(name)) {
			t.Errorf("IsReservedMachineName is `in` on a list: %q must not match", strings.ToUpper(name))
		}
	}
	if IsReservedMachineName("pc1") {
		t.Error("IsReservedMachineName(\"pc1\") = true")
	}
}

// TestConstantAccessorsCopy pins that a caller cannot mutate the package's
// state through the returned slice.
func TestConstantAccessorsCopy(t *testing.T) {
	first := ReservedMachineNames()
	first[0] = "clobbered"

	if second := ReservedMachineNames(); second[0] != "shared" {
		t.Errorf("ReservedMachineNames() returned an aliased slice: %v", second)
	}
}

// TestLiveIdentity compares the whole identity chain against what the oracle
// observed on this host. It is skipped when the fixture was generated
// somewhere else, since none of these values are portable; the byte-exactness
// of the chain itself is pinned by the tables above, which are.
func TestLiveIdentity(t *testing.T) {
	fixture := loadFixture(t)

	if nodeName() != fixture.Live.Node || os.Getuid() != fixture.Live.OsGetuid {
		t.Skipf("fixture was recorded on %q as uid %d; this is %q as uid %d",
			fixture.Live.Node, fixture.Live.OsGetuid, nodeName(), os.Getuid())
	}

	info, err := GetCurrentUserInfo()
	if err != nil {
		t.Fatalf("GetCurrentUserInfo: %v", err)
	}
	if info.Name != fixture.Live.PwName {
		t.Errorf("pw_name = %q, oracle says %q", info.Name, fixture.Live.PwName)
	}
	if info.UID != fixture.Live.PwUID {
		t.Errorf("pw_uid = %d, oracle says %d", info.UID, fixture.Live.PwUID)
	}
	if info.GID != fixture.Live.PwGID {
		t.Errorf("pw_gid = %d, oracle says %d", info.GID, fixture.Live.PwGID)
	}
	if info.HomeDir != fixture.Live.PwDir {
		t.Errorf("pw_dir = %q, oracle says %q", info.HomeDir, fixture.Live.PwDir)
	}

	uid, gid, err := GetCurrentUserUIDGID()
	if err != nil {
		t.Fatalf("GetCurrentUserUIDGID: %v", err)
	}
	if uid != fixture.Live.UID || gid != fixture.Live.GID {
		t.Errorf("uid/gid = %d/%d, oracle says %d/%d", uid, gid, fixture.Live.UID, fixture.Live.GID)
	}

	name, err := GetCurrentUserName()
	if err != nil {
		t.Fatalf("GetCurrentUserName: %v", err)
	}
	if name != fixture.Live.CurrentUserName {
		t.Errorf("GetCurrentUserName() = %q, oracle says %q", name, fixture.Live.CurrentUserName)
	}

	home, err := GetCurrentUserHome()
	if err != nil {
		t.Fatalf("GetCurrentUserHome: %v", err)
	}
	if home != fixture.Live.CurrentUserHome {
		t.Errorf("GetCurrentUserHome() = %q, oracle says %q", home, fixture.Live.CurrentUserHome)
	}

	admin, err := IsAdmin()
	if err != nil {
		t.Fatalf("IsAdmin: %v", err)
	}
	if admin != fixture.Live.IsAdmin {
		t.Errorf("IsAdmin() = %v, oracle says %v", admin, fixture.Live.IsAdmin)
	}

	if got := IsWSLPlatform(); got != fixture.Live.IsWSL {
		t.Errorf("IsWSLPlatform() = %v, oracle says %v", got, fixture.Live.IsWSL)
	}
}

// TestGetCurrentUserNameComposesTheChain pins the composition itself, on any
// host: the name is slug(login + "-" + hash(node)), with the hostname hashed
// and the login not.
func TestGetCurrentUserNameComposesTheChain(t *testing.T) {
	login := ""
	if info, err := GetCurrentUserInfo(); err == nil {
		login = info.Name
	} else if errors.Is(err, ErrNoPasswdDatabase) {
		// The Windows arm has no passwd database (Python's `lambda: None`);
		// the login comes from getpass's env chain instead. Pin the chain by
		// planting its first variable and asserting the composition uses it.
		t.Setenv("LOGNAME", "chainuser")
		login = "chainuser"
	} else {
		t.Fatalf("GetCurrentUserInfo: %v", err)
	}

	got, err := GetCurrentUserName()
	if err != nil {
		t.Fatalf("GetCurrentUserName: %v", err)
	}

	want := Slug(login + "-" + GenerateURLSafeHash(nodeName()))
	if got != want {
		t.Errorf("GetCurrentUserName() = %q, want %q", got, want)
	}
}

func TestPoolSizeIsPositive(t *testing.T) {
	// cpu_count() and runtime.NumCPU() can legitimately differ under a
	// cpuset, so only the property every caller relies on is asserted.
	if PoolSize() < 1 {
		t.Errorf("PoolSize() = %d", PoolSize())
	}
}

// ---------------------------------------------------------------------------
// exec_by_platform
// ---------------------------------------------------------------------------

// TestExecByPlatformArgumentOrder pins the argument order, which is the only
// thing about this function that can go wrong and the thing that would go
// wrong silently: three same-typed function arguments mean the compiler cannot
// catch a swap, and half the Python call sites are asymmetric.
func TestExecByPlatformArgumentOrder(t *testing.T) {
	got := ExecByPlatform(
		func() string { return Linux },
		func() string { return Windows },
		func() string { return MacOS },
	)

	if got != runtime.GOOS {
		t.Errorf("ExecByPlatform picked %q on %q", got, runtime.GOOS)
	}
}

// TestExecByPlatformCallsOneArm pins that the unselected arms are never
// evaluated: several Python call sites pass functions that import a
// platform-only module or touch a platform-only API.
func TestExecByPlatformCallsOneArm(t *testing.T) {
	calls := 0
	count := func() func() int {
		return func() int { calls++; return calls }
	}

	ExecByPlatform(count(), count(), count())

	if calls != 1 {
		t.Errorf("%d arms were evaluated, want 1", calls)
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}
